import { test, expect } from '@playwright/test';

test.describe('Notification Panel', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display notification panel sliding in from the top', async ({ page }) => {
    // Trigger notification
    const triggerButton = page.getByRole('button', { name: /show notification/i });
    await triggerButton.click();

    // Check notification panel is visible
    const notificationPanel = page.getByRole('region', { name: /notification/i });
    await expect(notificationPanel).toBeVisible();

    // Verify it's positioned at the top
    const boundingBox = await notificationPanel.boundingBox();
    expect(boundingBox?.y).toBeLessThan(100);
  });

  test('should animate notification panel with slide-in effect', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: /show notification/i });
    await triggerButton.click();

    const notificationPanel = page.getByRole('region', { name: /notification/i });

    // Check for animation class or transform property
    const hasAnimationClass = await notificationPanel.evaluate((el) => {
      const classes = el.className;
      const styles = window.getComputedStyle(el);
      return classes.includes('slide') || styles.animation.includes('slide') || styles.transform !== 'none';
    });

    expect(hasAnimationClass).toBeTruthy();
  });

  test('should close notification panel when dismiss button is clicked', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: /show notification/i });
    await triggerButton.click();

    const notificationPanel = page.getByRole('region', { name: /notification/i });
    await expect(notificationPanel).toBeVisible();

    const dismissButton = page.getByRole('button', { name: /close|dismiss/i });
    await dismissButton.click();

    await expect(notificationPanel).not.toBeVisible();
  });

  test('should display notification message content', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: /show notification/i });
    await triggerButton.click();

    const notificationMessage = page.getByText(/notification message|success|error|warning/i);
    await expect(notificationMessage).toBeVisible();
  });
});
